import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { getUser, logout } from '../../utils/auth';

const Header = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const user = getUser();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const dropdownRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    if (window.confirm('Apakah Anda yakin ingin logout?')) {
      logout();
      navigate('/login');
    }
  };

  const getNavItems = () => {
    if (!user) return [];

    const baseItems = [
      { name: 'Dashboard', path: '/user/dashboard', icon: '🏠' },
      { name: 'My Bookings', path: '/user/mybookings', icon: '📋' },
      { name: 'Buat Booking', path: '/user/booking', icon: '➕' }
    ];

    if (user.role === 'admin') {
      return [
        { name: 'Admin Dashboard', path: '/admin/dashboard', icon: '👑' },
        { name: 'Manage Bookings', path: '/admin/bookings', icon: '📊' },
        { name: 'Manage Rooms', path: '/admin/rooms', icon: '🏢' },
        { name: 'Manage Users', path: '/admin/users', icon: '👥' },
        ...baseItems
      ];
    }

    if (user.role === 'zoom_approver') {
      return [
        { name: 'Zoom Dashboard', path: '/zoom/dashboard', icon: '💻' },
        { name: 'Zoom Requests', path: '/zoom/requests', icon: '📝' },
        ...baseItems
      ];
    }

    if (user.role === 'room_approver') {
      return [
        { name: 'Room Dashboard', path: '/room/dashboard', icon: '🏢' },
        { name: 'Room Requests', path: '/room/requests', icon: '📝' },
        ...baseItems
      ];
    }

    return baseItems;
  };

  const getRoleInfo = () => {
    const roleMap = {
      admin: { label: 'Administrator', color: 'bg-purple-100 text-purple-800', icon: '👑' },
      zoom_approver: { label: 'Zoom Approver', color: 'bg-blue-100 text-blue-800', icon: '💻' },
      room_approver: { label: 'Room Approver', color: 'bg-green-100 text-green-800', icon: '🏢' },
      user: { label: 'User', color: 'bg-gray-100 text-gray-800', icon: '👤' }
    };
    return roleMap[user?.role] || roleMap.user;
  };

  const isActivePath = (path) => {
    return location.pathname === path;
  };

  const navItems = getNavItems();
  const roleInfo = getRoleInfo();

  return (
    <header className="bg-white/95 backdrop-blur-md border-b border-gray-200/50 shadow-lg sticky top-0 z-50 transition-all duration-300">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo Section */}
          <div className="flex items-center">
            <div className="flex-shrink-0">
              <div className="flex items-center cursor-pointer group" onClick={() => navigate('/user/dashboard')}>
                <div className="w-10 h-10 bg-gradient-to-r from-primary-500 via-blue-500 to-purple-600 rounded-xl flex items-center justify-center mr-3 shadow-lg group-hover:scale-110 transition-transform duration-300">
                  <span className="text-white text-lg font-bold">🏢</span>
                </div>
                <div>
                  <h1 className="text-xl font-bold bg-gradient-to-r from-primary-600 to-blue-600 bg-clip-text text-transparent">
                    BRIRoom
                  </h1>
                  <p className="text-xs text-gray-500 -mt-1">Room Management</p>
                </div>
              </div>
            </div>

            {/* Desktop Navigation */}
            <nav className="hidden md:ml-8 md:flex md:space-x-1">
              {navItems.slice(0, 4).map((item) => (
                <button
                  key={item.path}
                  onClick={() => navigate(item.path)}
                  className={`px-4 py-2 rounded-xl text-sm font-medium transition-all duration-300 flex items-center group ${
                    isActivePath(item.path)
                      ? 'bg-gradient-to-r from-primary-500 to-blue-600 text-white shadow-lg'
                      : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                  }`}
                >
                  <span className="mr-2 group-hover:scale-110 transition-transform duration-300">
                    {item.icon}
                  </span>
                  {item.name}
                </button>
              ))}
            </nav>
          </div>

          {/* User Menu */}
          <div className="flex items-center space-x-4">
            {/* Quick Actions (Desktop) */}
            <div className="hidden lg:flex items-center space-x-2">
              <button
                onClick={() => navigate('/user/booking')}
                className="inline-flex items-center px-4 py-2 bg-gradient-to-r from-primary-600 to-blue-600 hover:from-primary-700 hover:to-blue-700 text-white text-sm font-medium rounded-xl transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-xl group"
              >
                <svg className="w-4 h-4 mr-2 group-hover:rotate-90 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                </svg>
                Quick Book
              </button>
            </div>

            {/* User Dropdown */}
            <div className="relative" ref={dropdownRef}>
              <button
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="flex items-center px-4 py-2 text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 rounded-xl border border-gray-200 hover:border-gray-300 transition-all duration-300 hover:shadow-lg group"
              >
                <div className="w-8 h-8 bg-gradient-to-r from-gray-400 to-gray-600 rounded-lg flex items-center justify-center mr-3 group-hover:scale-110 transition-transform duration-300">
                  <span className="text-white text-sm">{roleInfo.icon}</span>
                </div>
                <div className="hidden sm:block text-left mr-3">
                  <p className="text-sm font-semibold text-gray-900 truncate max-w-32">
                    {user?.name || user?.email}
                  </p>
                  <p className="text-xs text-gray-500">
                    {roleInfo.label}
                  </p>
                </div>
                <svg 
                  className={`w-5 h-5 text-gray-400 transition-transform duration-300 ${isDropdownOpen ? 'rotate-180' : ''}`} 
                  fill="none" 
                  stroke="currentColor" 
                  viewBox="0 0 24 24"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </button>

              {/* Dropdown Menu */}
              {isDropdownOpen && (
                <div className="absolute right-0 mt-3 w-80 bg-white/95 backdrop-blur-md rounded-2xl shadow-2xl border border-gray-200/50 overflow-hidden z-50 animate-fade-in">
                  {/* User Info Header */}
                  <div className="bg-gradient-to-r from-primary-600 via-blue-600 to-purple-600 px-6 py-4">
                    <div className="flex items-center">
                      <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center mr-4">
                        <span className="text-white text-xl">{roleInfo.icon}</span>
                      </div>
                      <div className="flex-1">
                        <h3 className="text-white font-semibold">{user?.name || user?.email}</h3>
                        <div className="flex items-center mt-1">
                          <span className={`inline-flex items-center px-2 py-1 rounded-lg text-xs font-medium ${roleInfo.color} bg-white/20 text-white`}>
                            {roleInfo.label}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Navigation Links */}
                  <div className="p-4">
                    <div className="space-y-1">
                      {navItems.map((item) => (
                        <button
                          key={item.path}
                          onClick={() => {
                            navigate(item.path);
                            setIsDropdownOpen(false);
                          }}
                          className={`w-full flex items-center px-4 py-3 text-sm font-medium rounded-xl transition-all duration-300 group ${
                            isActivePath(item.path)
                              ? 'bg-primary-50 text-primary-700 border border-primary-200'
                              : 'text-gray-700 hover:bg-gray-50 hover:text-gray-900'
                          }`}
                        >
                          <span className="mr-3 text-lg group-hover:scale-110 transition-transform duration-300">
                            {item.icon}
                          </span>
                          {item.name}
                          {isActivePath(item.path) && (
                            <span className="ml-auto w-2 h-2 bg-primary-600 rounded-full"></span>
                          )}
                        </button>
                      ))}
                    </div>

                    <div className="border-t border-gray-200 mt-4 pt-4">
                      <button
                        onClick={() => {
                          navigate('/user/profile');
                          setIsDropdownOpen(false);
                        }}
                        className="w-full flex items-center px-4 py-3 text-sm font-medium text-gray-700 hover:bg-gray-50 hover:text-gray-900 rounded-xl transition-all duration-300 group"
                      >
                        <span className="mr-3 text-lg group-hover:scale-110 transition-transform duration-300">⚙️</span>
                        Settings & Profile
                      </button>
                      
                      <button
                        onClick={handleLogout}
                        className="w-full flex items-center px-4 py-3 text-sm font-medium text-red-600 hover:bg-red-50 hover:text-red-700 rounded-xl transition-all duration-300 group"
                      >
                        <span className="mr-3 text-lg group-hover:scale-110 transition-transform duration-300">🚪</span>
                        Logout
                      </button>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Mobile menu button */}
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="md:hidden inline-flex items-center p-2 rounded-xl text-gray-400 hover:text-gray-500 hover:bg-gray-100 transition-all duration-300"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                {isMobileMenuOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>

        {/* Mobile Navigation Menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden">
            <div className="px-2 pt-2 pb-6 space-y-1 bg-white/95 backdrop-blur-md border-t border-gray-200/50">
              {navItems.map((item) => (
                <button
                  key={item.path}
                  onClick={() => {
                    navigate(item.path);
                    setIsMobileMenuOpen(false);
                  }}
                  className={`w-full flex items-center px-4 py-3 text-sm font-medium rounded-xl transition-all duration-300 group ${
                    isActivePath(item.path)
                      ? 'bg-gradient-to-r from-primary-500 to-blue-600 text-white shadow-lg'
                      : 'text-gray-700 hover:bg-gray-100 hover:text-gray-900'
                  }`}
                >
                  <span className="mr-3 text-lg group-hover:scale-110 transition-transform duration-300">
                    {item.icon}
                  </span>
                  {item.name}
                </button>
              ))}
              
              {/* Mobile Quick Actions */}
              <div className="pt-4 border-t border-gray-200">
                <button
                  onClick={() => {
                    navigate('/user/booking');
                    setIsMobileMenuOpen(false);
                  }}
                  className="w-full flex items-center justify-center px-4 py-3 bg-gradient-to-r from-primary-600 to-blue-600 hover:from-primary-700 hover:to-blue-700 text-white text-sm font-medium rounded-xl transition-all duration-300 transform hover:scale-105 shadow-lg"
                >
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                  </svg>
                  Buat Booking Baru
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
